B.jb=s([B.i8,B.m4],t.YD)
B.agg=s(["{name}, {what} i\xe7in \xe7ok te\u015fekk\xfcr ederim! Ger\xe7ekten \xe7ok i\u015fime yarad\u0131, sana bir kahve borcum var. \u2615","\xc7ok sa\u011f ol {name}! {what} i\xe7in ay\u0131rd\u0131\u011f\u0131n zaman ve emek benim i\xe7in \xe7ok de\u011ferli."],t.s)
B.aj_=s(["Say\u0131n {name}, {what} konusundaki deste\u011finiz i\xe7in te\u015fekk\xfcr ederim. Yard\u0131m\u0131n\u0131z \xe7ok de\u011ferliydi.","{name}, {what} i\xe7in g\xf6sterdi\u011finiz ilgi ve emek i\xe7in i\xe7tenlikle te\u015fekk\xfcr ederim."],t.s)
